const before = await client.items.find<Schema.Article>("article-1", { nested: true });
const untouchedBefore = before.untouched;
const bodyBefore = JSON.stringify(before.body);

await client.items.update<Schema.Article>(before.id, {
  title: "Summer update",
  meta: { current_version: before.meta.current_version },
});

const after = await client.items.find<Schema.Article>("article-1", { nested: true });
if (
  after.title !== "Summer update" ||
  after.untouched !== untouchedBefore ||
  JSON.stringify(after.body) !== bodyBefore ||
  after.meta.status !== "draft"
) {
  throw new Error("Post-update verification failed");
}

console.log({
  id: after.id,
  title: after.title,
  status: after.meta.status,
  untouchedUnchanged: after.untouched === untouchedBefore,
  bodyUnchanged: JSON.stringify(after.body) === bodyBefore,
});

