const article = await client.items.find<Schema.Article>("article-1", { nested: true });

const english = article.body.en;
if (!english) {
  throw new Error("English body is missing");
}

let greetingCount = 0;
let imageBlockCount = 0;
const content = mapNodes(english, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingCount += 1;
    return { ...node, value: "Welcome reader" };
  }

  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    imageBlockCount += 1;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        caption: "Summer portrait",
      }),
    };
  }

  return node;
});

if (greetingCount !== 1 || imageBlockCount !== 1) {
  throw new Error("Expected exactly one greeting span and one image block");
}

content.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

const updated = await client.items.update<Schema.Article>(article.id, {
  body: { en: content, it: article.body.it },
  meta: { current_version: article.meta.current_version },
});

const updatedEnglish = updated.body.en;
if (!updatedEnglish) {
  throw new Error("Updated English body is missing");
}

let welcomeCount = 0;
let updatedCaptionCount = 0;
let finalParagraphCount = 0;
mapNodes(updatedEnglish, (node) => {
  if (isSpan(node) && node.value === "Welcome reader") {
    welcomeCount += 1;
  }
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1" && node.item.attributes.caption === "Summer portrait") {
    updatedCaptionCount += 1;
  }
  return node;
});

const finalNode = updatedEnglish.document.children[updatedEnglish.document.children.length - 1];
if (isParagraph(finalNode) && finalNode.children.length === 1) {
  const finalChild = finalNode.children[0];
  if (isSpan(finalChild) && finalChild.value === "See you soon.") {
    finalParagraphCount = 1;
  }
}

if (welcomeCount !== 1 || updatedCaptionCount !== 1 || finalParagraphCount !== 1) {
  throw new Error("Post-update verification failed");
}

console.log({
  status: updated.meta.status,
  greetingChanged: welcomeCount === 1,
  imageCaptionChanged: updatedCaptionCount === 1,
  finalParagraphAppended: finalParagraphCount === 1,
  italianLocalePreserved: JSON.stringify(updated.body.it) === JSON.stringify(article.body.it),
});

