const before = await client.items.find<Schema.Article>("article-1");
const beforeBodyEn = before.body.en ? serialize(before.body.en) : null;
const beforeBodyIt = before.body.it ? serialize(before.body.it) : null;

await client.items.update<Schema.Article>(before.id, {
  title: "Summer update",
  meta: { current_version: before.meta.current_version },
});

const after = await client.items.find<Schema.Article>(before.id);
const otherFieldsUnchanged =
  after.untouched === before.untouched &&
  (after.body.en ? serialize(after.body.en) : null) === beforeBodyEn &&
  (after.body.it ? serialize(after.body.it) : null) === beforeBodyIt;

if (after.title !== "Summer update" || !otherFieldsUnchanged || after.meta.status !== "draft") {
  throw new Error("Post-update verification failed");
}

console.log({
  id: after.id,
  title: after.title,
  other_fields_unchanged: otherFieldsUnchanged,
  status: after.meta.status,
});

