const article = await client.items.find<Schema.Article>("article-1", { nested: true });

if (article.body.en === null) {
  throw new Error("English body is empty");
}

let greetingChanged = false;
let captionChanged = false;

let englishBody = mapNodes(article.body.en, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingChanged = true;
    return { ...node, value: "Welcome reader" };
  }

  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    captionChanged = true;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        caption: "Summer portrait",
      }),
    };
  }

  return node;
});

if (!greetingChanged || !captionChanged) {
  throw new Error("Expected greeting span or image block was not found");
}

englishBody.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

const updated = await client.items.update<Schema.Article>(article.id, {
  body: { ...article.body, en: englishBody },
  meta: { current_version: article.meta.current_version },
});

console.log({
  id: updated.id,
  status: updated.meta.status,
  englishBody: serialize(updated.body.en),
  italianPreserved: serialize(updated.body.it),
});

const article = await client.items.find<Schema.Article>("article-1", { nested: true });

if (article.body.en === null) {
  throw new Error("English body is empty");
}

let greetingValue = "";
let greetingMarks = "";
let linkUrl = "";
let blockCaption = "";
let blockImage = "";

mapNodes(article.body.en, (node) => {
  if (isSpan(node) && node.value === "Welcome reader") {
    greetingValue = node.value;
    greetingMarks = (node.marks ?? []).join(",");
  }
  if (isLink(node)) {
    linkUrl = node.url;
  }
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    blockCaption = node.item.attributes.caption;
    blockImage = node.item.attributes.image === null ? "null" : "present";
  }
  return node;
});

console.log({
  status: article.meta.status,
  greetingValue,
  greetingMarks,
  linkUrl,
  blockIdPresent: serialize(article.body.en).includes("<block id=\"block-1\"/>"),
  blockCaption,
  blockImage,
  english: serialize(article.body.en),
  italian: article.body.it === null ? null : serialize(article.body.it),
});

