const currentItem = await client.items.find<Schema.Article>("article-1", { nested: true });

if (currentItem.body.en) {
  let greetingCount = 0;
  let imageBlockCount = 0;
  let content: Dast = mapNodes(currentItem.body.en, (node) => {
    if (isSpan(node) && node.value === "Hello reader") {
      greetingCount += 1;
      return { ...node, value: "Welcome reader" };
    }
    if (
      isBlockWithItemOfType(Schema.ImageBlock.ID, node) &&
      node.item.id === "block-1"
    ) {
      imageBlockCount += 1;
      return {
        ...node,
        item: buildBlockRecord<Schema.ImageBlock>({
          id: node.item.id,
          caption: "Summer portrait",
        }),
      };
    }
    return node;
  });

  if (greetingCount === 1 && imageBlockCount === 1) {
    content.document.children.push({
      type: "paragraph",
      children: [{ type: "span", value: "See you soon." }],
    });
    const updated = await client.items.update<Schema.Article>(currentItem.id, {
      body: { ...currentItem.body, en: content },
      meta: { current_version: currentItem.meta.current_version },
    });
    console.log({
      id: updated.id,
      status: updated.meta.status,
      greetingCount,
      imageBlockCount,
      englishNodeCount: content.document.children.length,
    });
  } else {
    console.log({ greetingCount, imageBlockCount, updated: false });
  }
}

const item = await client.items.find<Schema.Article>("article-1", { nested: true });

if (item.body.en && item.body.it) {
  let greeting = "";
  let caption = "";
  for (const node of item.body.en.document.children) {
    if (isParagraph(node)) {
      for (const child of node.children) {
        if (isSpan(child) && child.value === "Welcome reader") greeting = child.value;
      }
    }
    if (
      isBlockWithItemOfType(Schema.ImageBlock.ID, node) &&
      node.item.id === "block-1"
    ) {
      caption = node.item.attributes.caption;
    }
  }
  const lastNode = item.body.en.document.children[item.body.en.document.children.length - 1];
  let finalParagraph = "";
  if (isParagraph(lastNode) && lastNode.children.length === 1) {
    const child = lastNode.children[0];
    if (isSpan(child)) finalParagraph = child.value;
  }
  console.log({
    status: item.meta.status,
    greeting,
    caption,
    finalParagraph,
    italianPresent: item.body.it !== null,
  });
}

