const article = await client.items.find<Schema.Article>("article-1", { nested: true });

const english = article.body.en;
if (!english) {
  throw new Error("English body is missing");
}

let greetingCount = 0;
let blockCount = 0;
let updatedEnglish = mapNodes(english, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingCount += 1;
    return { ...node, value: "Welcome reader" };
  }
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    blockCount += 1;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        caption: "Summer portrait",
      }),
    };
  }
  return node;
});

if (greetingCount !== 1 || blockCount !== 1) {
  throw new Error("Expected one greeting span and one image block");
}

updatedEnglish.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

const body: FieldValueInRequest<typeof article, "body"> = {
  ...article.body,
  en: updatedEnglish,
};

const updated = await client.items.update<Schema.Article>(article.id, {
  body,
  meta: { current_version: article.meta.current_version },
});

console.log({
  id: updated.id,
  status: updated.meta.status,
  english: serialize(updated.body.en),
  italian: serialize(updated.body.it),
});

const article = await client.items.find<Schema.Article>("article-1", { nested: true });
const english = article.body.en;
const italian = article.body.it;

if (!english || !italian) {
  throw new Error("Expected both locales");
}

const greeting = findFirstNode(english, (node) => isSpan(node) && node.value === "Welcome reader");
const imageBlock = findFirstNode(
  english,
  (node) => isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1",
);

console.log({
  status: article.meta.status,
  english: serialize(english),
  greetingMarks: greeting && isSpan(greeting.node) ? greeting.node.marks : null,
  imageBlock: imageBlock && isBlock(imageBlock.node) ? {
    id: imageBlock.node.item.id,
    caption: imageBlock.node.item.attributes.caption,
    image: imageBlock.node.item.attributes.image,
  } : null,
  italian: serialize(italian),
});

