const before = await client.items.find<Schema.Article>("article-1", { nested: true });
const updated = await client.items.update<Schema.Article>("article-1", {
  title: "Summer update",
  meta: { current_version: before.meta.current_version },
});
const after = await client.items.find<Schema.Article>("article-1", { nested: true });
const unchangedUntouched = before.untouched === after.untouched;
const unchangedBody = JSON.stringify(before.body) === JSON.stringify(after.body);
const remainsDraft = after.meta.status === "draft";
if (!unchangedUntouched || !unchangedBody || !remainsDraft || updated.title !== "Summer update") {
  throw new Error("Post-update verification failed");
}
console.log({
  id: after.id,
  title: after.title,
  status: after.meta.status,
  unchangedUntouched,
  unchangedBody,
});

