const before = await client.items.find<Schema.Article>("article-1", { nested: true });
const beforeUntouched = before.untouched;
const beforeBody = JSON.stringify(before.body);
const updated = await client.items.update<Schema.Article>(before.id, {
  title: "Summer update",
  meta: { current_version: before.meta.current_version },
});
const after = await client.items.find<Schema.Article>("article-1", { nested: true });
console.log(JSON.stringify({
  title: after.title,
  titleChanged: before.title !== after.title,
  untouchedUnchanged: beforeUntouched === after.untouched,
  bodyUnchanged: beforeBody === JSON.stringify(after.body),
  status: after.meta.status,
  updateReturnedStatus: updated.meta.status
}));

const record = await client.items.find<Schema.Article>("article-1", { nested: true });
console.log(JSON.stringify({
  id: record.id,
  title: record.title,
  untouched: record.untouched,
  body: record.body,
