if (article.body.en === null) {
  throw new Error("English body is empty");
}

let greetingMatches = 0;
let blockMatches = 0;

const englishBody = mapNodes(article.body.en, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingMatches += 1;
    return { ...node, value: "Welcome reader" };
  }

  if (
    isBlockWithItemOfType(Schema.ImageBlock.ID, node) &&
    node.item.id === "block-1"
  ) {
    blockMatches += 1;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        caption: "Summer portrait",
      }),
    };
  }

  return node;
});

if (greetingMatches !== 1 || blockMatches !== 1) {
  throw new Error("Expected exactly one greeting and one image block");
}

englishBody.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

