const currentItem = await client.items.find<Schema.Article>("article-1", { nested: true });
const english = currentItem.body.en;

if (!english) {
  throw new Error("English body is missing");
}

let greetingChanged = false;
let captionChanged = false;

let content = mapNodes(english, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingChanged = true;
    return { ...node, value: "Welcome reader" };
  }

  if (isBlock(node) && node.item.id === "block-1") {
    captionChanged = true;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        caption: "Summer portrait",
        image: node.item.attributes.image,
      }),
    };
  }

  return node;
});

if (!greetingChanged || !captionChanged) {
  throw new Error("Expected greeting span or image block was not found");
}

content.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

const updated = await client.items.update<Schema.Article>(currentItem.id, {
  body: { ...currentItem.body, en: content },
  meta: { current_version: currentItem.meta.current_version },
});

console.log({
  id: updated.id,
  status: updated.meta.status,
  greetingChanged,
  captionChanged,
  appendedFinalParagraph: true,
});

const currentItem = await client.items.find<Schema.Article>("article-1", { nested: true });
const english = currentItem.body.en;
const italian = currentItem.body.it;

if (!english || !italian) {
  throw new Error("Expected both locales");
}

const greeting = findFirstNode(english, (node) => isSpan(node) && node.value === "Welcome reader");
const imageBlock = findFirstNode(english, (node) => isBlock(node) && node.item.id === "block-1");
const finalNode = english.document.children[english.document.children.length - 1];
const finalParagraphOk =
  isParagraph(finalNode) &&
  finalNode.children.length === 1 &&
  isSpan(finalNode.children[0]) &&
  finalNode.children[0].value === "See you soon.";

if (!greeting || !imageBlock || !finalParagraphOk) {
  throw new Error("English verification failed");
}

console.log({
  status: currentItem.meta.status,
  greetingMarks: greeting.node.marks ?? [],
  blockId: imageBlock.node.item.id,
  caption: imageBlock.node.item.attributes.caption,
  image: imageBlock.node.item.attributes.image,
  finalParagraphOk,
  italian: serialize(italian),
});

