const currentItem = await client.items.find<Schema.Article>("article-1", { nested: true });
const english = currentItem.body.en;

if (!english) {
  throw new Error("English body is missing");
}

let greetingChanged = false;
let captionChanged = false;

let updatedEnglish = mapNodes(english, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingChanged = true;
    return { ...node, value: "Welcome reader" };
  }

  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    captionChanged = true;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        caption: "Summer portrait",
      }),
    };
  }

  return node;
});

if (!greetingChanged) {
  throw new Error('Greeting span "Hello reader" was not found');
}
if (!captionChanged) {
  throw new Error('Image block "block-1" was not found');
}

updatedEnglish.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

const updated = await client.items.update<Schema.Article>(currentItem.id, {
  body: { ...currentItem.body, en: updatedEnglish },
  meta: { current_version: currentItem.meta.current_version },
});

console.log({
  id: updated.id,
  status: updated.meta.status,
  englishBodyUpdated: updated.body.en !== null,
  italianBodyPreserved: updated.body.it === currentItem.body.it,
});

const record = await client.items.find<Schema.Article>("article-1", { nested: true });
