  throw new Error("English body is missing after update");
}

const greeting = findFirstNode(english, (node) => isSpan(node) && node.value === "Welcome reader");
const imageBlock = findFirstNode(
  english,
  (node) => isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1",
);
const finalNode = english.document.children[english.document.children.length - 1];
const finalParagraph = finalNode && isParagraph(finalNode)
  ? finalNode.children.length === 1 && isSpan(finalNode.children[0]) && finalNode.children[0].value === "See you soon."
  : false;

console.log({
  status: record.meta.status,
  greetingUpdated: greeting !== undefined,
  blockCaption: imageBlock && isBlock(imageBlock.node) ? imageBlock.node.item.attributes.caption : null,
  finalParagraph,
  italianLocalePresent: italian !== null,
});

