const before = await client.items.find<Schema.Article>("article-1", { nested: true });

if (!before.body.en) {
  throw new Error("English body is missing");
}

const italianBefore = JSON.stringify(before.body.it);
const titleBefore = before.title;
const untouchedBefore = before.untouched;
let greetingMatches = 0;
let imageBlockMatches = 0;

let english: NonNullable<FieldValueInRequest<typeof before, "body">>["en"] =
  mapNodes(before.body.en, (node) => {
    if (isSpan(node) && node.value === "Hello reader") {
      greetingMatches++;
      return { ...node, value: "Welcome reader" };
    }
    if (
      isBlockWithItemOfType(Schema.ImageBlock.ID, node) &&
      node.item.id === "block-1"
    ) {
      imageBlockMatches++;
      return {
        ...node,
        item: buildBlockRecord<Schema.ImageBlock>({
          id: node.item.id,
          caption: "Summer portrait",
        }),
      };
    }
    return node;
  });

if (greetingMatches !== 1 || imageBlockMatches !== 1) {
  throw new Error("Expected greeting span or image block was not found exactly once");
}

english.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

await client.items.update<Schema.Article>(before.id, {
  body: { ...before.body, en: english },
  meta: { current_version: before.meta.current_version },
});

const after = await client.items.find<Schema.Article>("article-1", { nested: true });
console.log({
  status: after.meta.status,
  titlePreserved: after.title === titleBefore,
  untouchedPreserved: after.untouched === untouchedBefore,
  italianPreserved: JSON.stringify(after.body.it) === italianBefore,
  english: after.body.en,
});

