const before = await client.items.find<Schema.Article>("article-1", { nested: true });

if (!before.body.en || !before.body.it) {
  throw new Error("Expected both English and Italian body values");
}

const italianBefore = JSON.stringify(before.body.it);
const titleBefore = before.title;
const untouchedBefore = before.untouched;
let greetingCount = 0;
let imageBlockCount = 0;

let english: NonNullable<FieldValueInRequest<typeof before, "body">["en"]> = before.body.en;
english = mapNodes(english, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingCount++;
    return { ...node, value: "Welcome reader" };
  }
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    imageBlockCount++;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        caption: "Summer portrait",
      }),
    };
  }
  return node;
});

if (greetingCount !== 1 || imageBlockCount !== 1) {
  throw new Error("Expected exactly one greeting span and one image block");
}

english.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

await client.items.update<Schema.Article>("article-1", {
  body: { ...before.body, en: english },
  meta: { current_version: before.meta.current_version },
});

const after = await client.items.find<Schema.Article>("article-1", { nested: true });
if (!after.body.en || !after.body.it) {
  throw new Error("Saved body is missing an expected locale");
}
if (
  JSON.stringify(after.body.it) !== italianBefore ||
  after.title !== titleBefore ||
  after.untouched !== untouchedBefore ||
  after.meta.status !== "draft"
) {
  throw new Error("An unrelated locale, field, or publication state changed");
}

let welcomeCount = 0;
let finalParagraphCount = 0;
let verifiedBlockCount = 0;
let imagePreserved = false;

for (const node of after.body.en.document.children) {
  if (isParagraph(node) && node.children.length === 1 && isSpan(node.children[0]) && node.children[0].value === "See you soon.") {
    finalParagraphCount++;
  }
}

mapNodes(after.body.en, (node) => {
  if (isSpan(node) && node.value === "Welcome reader") {
    welcomeCount++;
  }
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    verifiedBlockCount++;
    imagePreserved = node.item.attributes.image === null && node.item.attributes.caption === "Summer portrait";
  }
  return node;
});

if (welcomeCount !== 1 || finalParagraphCount !== 1 || verifiedBlockCount !== 1 || !imagePreserved) {
  throw new Error("Saved English Structured Text did not match the requested edits");
}

console.log("Verified: English greeting, image caption, final paragraph; Italian body, unrelated fields, block image/ID, and draft status preserved.");

