const before = await client.items.find<Schema.Article>("article-1", { nested: true });

if (before.body.en === null) {
  throw new Error("English body is missing");
}

let greetingChanged = false;
let captionChanged = false;
let content: NonNullable<FieldValueInRequest<typeof before, "body">>["en"] = before.body.en;

content = mapNodes(content, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingChanged = true;
    return { ...node, value: "Welcome reader" };
  }

  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    captionChanged = true;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        caption: "Summer portrait",
      }),
    };
  }

  return node;
});

if (!greetingChanged) {
  throw new Error('Greeting span "Hello reader" was not found');
}

if (!captionChanged) {
  throw new Error('Image block "block-1" was not found');
}

content.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

await client.items.update<Schema.Article>(before.id, {
  body: { ...before.body, en: content },
  meta: { current_version: before.meta.current_version },
});

console.log({
  recordId: before.id,
  greetingChanged,
  captionChanged,
  appendedParagraph: "See you soon.",
});

const current = await client.items.find<Schema.Article>("article-1", { nested: true });

if (current.body.en === null || current.body.it === null) {
  throw new Error("Expected both English and Italian bodies");
}

const finalChild = current.body.en.document.children[current.body.en.document.children.length - 1];
const finalParagraphOk =
  finalChild !== undefined &&
